    extends BufferedParticleBatch<PointSpriteControllerRenderData> {
  private static boolean pointSpritesEnabled = false;
  protected static final Vector3 TMP_V1 = new Vector3();
  protected static final int sizeAndRotationUsage = 1 << 9;
  protected static final VertexAttributes CPU_ATTRIBUTES =
      new VertexAttributes(
          new VertexAttribute(Usage.Position, 3, ShaderProgram.POSITION_ATTRIBUTE),
          new VertexAttribute(Usage.ColorUnpacked, 4, ShaderProgram.COLOR_ATTRIBUTE),
          new VertexAttribute(Usage.TextureCoordinates, 4, "a_region"),
          new VertexAttribute(sizeAndRotationUsage, 3, "a_sizeAndRotation"));
  protected static final int CPU_VERTEX_SIZE = (short) (CPU_ATTRIBUTES.vertexSize / 4),
      CPU_POSITION_OFFSET = (short) (CPU_ATTRIBUTES.findByUsage(Usage.Position).offset / 4),
      CPU_COLOR_OFFSET = (short) (CPU_ATTRIBUTES.findByUsage(Usage.ColorUnpacked).offset / 4),
      CPU_REGION_OFFSET = (short) (CPU_ATTRIBUTES.findByUsage(Usage.TextureCoordinates).offset / 4),
      CPU_SIZE_AND_ROTATION_OFFSET =
          (short) (CPU_ATTRIBUTES.findByUsage(sizeAndRotationUsage).offset / 4);

  private static void enablePointSprites() {
    Gdx.gl.glEnable(GL20.GL_VERTEX_PROGRAM_POINT_SIZE);
    if (Gdx.app.getType() == ApplicationType.Desktop) {
      Gdx.gl.glEnable(0x8861); // GL_POINT_OES
    }
    pointSpritesEnabled = true;
  }

  @Nullable private float[] vertices;
  Renderable renderable;
  @Nullable protected BlendingAttribute blendingAttribute;
  @Nullable protected DepthTestAttribute depthTestAttribute;

  public PointSpriteParticleBatch() {
    this(1000);
  }

  public PointSpriteParticleBatch(int capacity) {
    this(capacity, new ParticleShader.Config(ParticleType.Point));
  }

  public PointSpriteParticleBatch(int capacity, ParticleShader.Config shaderConfig) {
    this(capacity, shaderConfig, null, null);
  }

  public PointSpriteParticleBatch(
      int capacity,
      ParticleShader.Config shaderConfig,
      @Nullable BlendingAttribute blendingAttribute,
      @Nullable DepthTestAttribute depthTestAttribute) {
    super(capacity);
    this.blendingAttribute = blendingAttribute;
    this.depthTestAttribute = depthTestAttribute;
    allocRenderable();
    ensureCapacity(capacity);
  }

  @Override
  public void allocParticlesData(int capacity) {
    vertices = new float[capacity * CPU_VERTEX_SIZE];
    renderable.meshPart.mesh = new Mesh(false, capacity, 0, CPU_ATTRIBUTES);
  }

  @Override
  public void ensureCapacity(int capacity) {
    if (vertices == null || vertices.length < capacity * CPU_VERTEX_SIZE) {
      float[] newVertices = new float[capacity * CPU_VERTEX_SIZE];
      if (vertices != null) {
        System.arraycopy(vertices, 0, newVertices, 0, vertices.length);
      }
      vertices = newVertices;
      Mesh oldMesh = renderable.meshPart.mesh;
      renderable.meshPart.mesh = new Mesh(false, capacity, 0, CPU_ATTRIBUTES);
      oldMesh.dispose();
    }
  }

  protected void allocRenderable() {
    renderable = new Renderable();
    renderable.meshPart.primitiveType = GL20.GL_POINTS;
    renderable.meshPart.offset = 0;
    renderable.material =
        new Material(
            blendingAttribute, depthTestAttribute, TextureAttribute.createDiffuse((Texture) null));
  }

  public void setTexture(Texture texture) {
    TextureAttribute attribute =
        (TextureAttribute) renderable.material.get(TextureAttribute.Diffuse);
    attribute.textureDescription.texture = texture;
  }

  public Texture getTexture() {
    TextureAttribute attribute =
        (TextureAttribute) renderable.material.get(TextureAttribute.Diffuse);
    return attribute.textureDescription.texture;
  }

  @Nullable
  public BlendingAttribute getBlendingAttribute() {
    return blendingAttribute;
  }

  @Override
  protected void flush(int[] offsets) {
    int tp = 0;
    for (PointSpriteControllerRenderData data : renderData) {
      FloatChannel scaleChannel = data.scaleChannel;
      FloatChannel regionChannel = data.regionChannel;
      FloatChannel positionChannel = data.positionChannel;
      FloatChannel colorChannel = data.colorChannel;
      FloatChannel rotationChannel = data.rotationChannel;
      if (rotationChannel == null) {
        continue;
      }
      FloatChannel rotationChannelNonNull = rotationChannel;

      for (int p = 0; p < data.controller.particles.size; ++p, ++tp) {
        int offset = offsets[tp] * CPU_VERTEX_SIZE;
        int regionOffset = p * regionChannel.strideSize;
        int positionOffset = p * positionChannel.strideSize;
        int colorOffset = p * colorChannel.strideSize;
        int rotationOffset = p * rotationChannelNonNull.strideSize;

        vertices[offset + CPU_POSITION_OFFSET] =
            positionChannel.data[positionOffset + ParticleChannels.XOffset];
        vertices[offset + CPU_POSITION_OFFSET + 1] =
            positionChannel.data[positionOffset + ParticleChannels.YOffset];
        vertices[offset + CPU_POSITION_OFFSET + 2] =
            positionChannel.data[positionOffset + ParticleChannels.ZOffset];
        vertices[offset + CPU_COLOR_OFFSET] =
            colorChannel.data[colorOffset + ParticleChannels.RedOffset];
        vertices[offset + CPU_COLOR_OFFSET + 1] =
            colorChannel.data[colorOffset + ParticleChannels.GreenOffset];
        vertices[offset + CPU_COLOR_OFFSET + 2] =
            colorChannel.data[colorOffset + ParticleChannels.BlueOffset];
        vertices[offset + CPU_COLOR_OFFSET + 3] =
            colorChannel.data[colorOffset + ParticleChannels.AlphaOffset];
        vertices[offset + CPU_SIZE_AND_ROTATION_OFFSET] =
            scaleChannel.data[p * scaleChannel.strideSize];
        vertices[offset + CPU_SIZE_AND_ROTATION_OFFSET + 1] =
            rotationChannelNonNull.data[rotationOffset + ParticleChannels.CosineOffset];
        vertices[offset + CPU_SIZE_AND_ROTATION_OFFSET + 2] =
            rotationChannelNonNull.data[rotationOffset + ParticleChannels.SineOffset];
        vertices[offset + CPU_REGION_OFFSET] =
            regionChannel.data[regionOffset + ParticleChannels.UOffset];
        vertices[offset + CPU_REGION_OFFSET + 1] =
            regionChannel.data[regionOffset + ParticleChannels.VOffset];
        vertices[offset + CPU_REGION_OFFSET + 2] =
            regionChannel.data[regionOffset + ParticleChannels.U2Offset];
        vertices[offset + CPU_REGION_OFFSET + 3] =
            regionChannel.data[regionOffset + ParticleChannels.V2Offset];
      }
    }

    renderable.meshPart.size = bufferedParticlesCount;
    renderable.meshPart.mesh.setVertices(vertices, 0, bufferedParticlesCount * CPU_VERTEX_SIZE);
    renderable.meshPart.update();
  }

  @Override
  public void getRenderables(Array<Renderable> renderables, Pool<Renderable> pool) {
    if (bufferedParticlesCount > 0) renderables.add(pool.obtain().set(renderable));
  }

  @Override
  public void save(AssetManager manager, ResourceData resources) {
    SaveData data = resources.createSaveData("pointSpriteBatch");
    data.saveAsset(manager.getAssetFileName(getTexture()), Texture.class);
  }

  @Override
  public void load(AssetManager manager, ResourceData resources) {
    SaveData data = resources.getSaveData("pointSpriteBatch");
    if (data != null) setTexture((Texture) manager.get(data.loadAsset()));
  }
}
